package vcs

import (
	"context"
	"os"
	"path/filepath"
	"strings"
)

// CheckoutIdentity returns the path of the repository whose refs repoPath
// works on. A git worktree and a jj workspace share their parent's object
// store and branch list, so both resolve to the parent; every other checkout
// resolves to itself. Fleet-wide joins key on this to avoid counting one
// branch once per checkout that can see it.
//
// The answer comes from the pointer files git and jj write into a linked
// checkout, so it costs no subprocess and works for a repo that no longer
// exists.
func CheckoutIdentity(repoPath string) string {
	if parent, ok := gitWorktreeParent(repoPath); ok {
		return parent
	}
	if parent, ok := jjWorkspaceParent(repoPath); ok {
		return parent
	}

	return repoPath
}

// RemoteIdentity derives a key for the repository a remote URL names:
// "host/owner/repo", lowercased. Every checkout of one remote shares it,
// whatever URL form or casing each was cloned with, since GitHub treats
// Owner/Repo and owner/repo as one repository. The host is part of the key so
// an Enterprise "acme/tools" does not collide with a github.com one. A URL
// that names no repository yields "".
//
// Unlike ExtractRepoPath this keeps the full path, so a GitLab subgroup is
// distinct from a repo of the same name under another subgroup.
func RemoteIdentity(remoteURL string) string {
	url := strings.TrimSuffix(strings.TrimSpace(remoteURL), ".git")
	if _, after, ok := strings.Cut(url, "://"); ok {
		url = after
	}
	if _, after, ok := strings.Cut(url, "@"); ok {
		url = after
	}

	host, repoPath, isSCP := strings.Cut(url, ":")
	if isSCP {
		if port, rest, hasPath := strings.Cut(repoPath, "/"); hasPath && isAllDigits(port) {
			repoPath = rest
		}
	} else if host, repoPath, _ = strings.Cut(url, "/"); host == "" {
		return ""
	}

	repoPath = strings.Trim(repoPath, "/")
	if host == "" || !strings.Contains(repoPath, "/") {
		return ""
	}

	return strings.ToLower(host + "/" + repoPath)
}

func isAllDigits(value string) bool {
	if value == "" {
		return false
	}

	return strings.IndexFunc(value, func(r rune) bool { return r < '0' || r > '9' }) < 0
}

// HostFromRemote extracts just the host portion of a git remote URL,
// lowercased. This is used to uniquely identify the host of a remote,
// which is important for distinguishing between different hosting
// services (e.g., GitHub vs GitLab).
//
// The parsing follows the same approach as RemoteIdentity to ensure
// consistency. It strips the scheme, user credentials, and splits
// on : for SCP-like URLs or / for HTTP(S) URLs.
func HostFromRemote(remoteURL string) string {
	url := strings.TrimSuffix(strings.TrimSpace(remoteURL), ".git")
	if _, after, ok := strings.Cut(url, "://"); ok {
		url = after
	}
	if _, after, ok := strings.Cut(url, "@"); ok {
		url = after
	}

	host, _, isSCP := strings.Cut(url, ":")
	if isSCP {
		// For SCP-like URLs (e.g., user@host:/path), host is the first part
		return strings.ToLower(host)
	}

	// For HTTP(S) URLs (e.g., host/path), split on /
	if host, _, _ = strings.Cut(url, "/"); host != "" {
		return strings.ToLower(host)
	}

	return ""
}

// RemoteIdentityFor resolves the RemoteIdentity of the checkout at repoPath,
// costing one git/jj call. Callers holding a models.RepoSummary should read
// its RemoteID instead of paying for this again.
func RemoteIdentityFor(ctx context.Context, repoPath string) string {
	url, err := GetOperations(repoPath).GetRemoteURL(ctx, repoPath)
	if err != nil {
		return ""
	}

	return RemoteIdentity(url)
}

// linkedParent returns the repo repoPath borrows its refs from, or "" when
// repoPath is a standalone checkout.
func linkedParent(repoPath string) string {
	if parent := CheckoutIdentity(repoPath); parent != repoPath {
		return parent
	}

	return ""
}

// gitWorktreeParent reads a linked worktree's ".git" file, which holds
// "gitdir: <parent>/.git/worktrees/<name>".
func gitWorktreeParent(repoPath string) (string, bool) {
	contents, ok := pointerFile(filepath.Join(repoPath, ".git"))
	if !ok {
		return "", false
	}

	gitDir, ok := strings.CutPrefix(contents, "gitdir:")
	if !ok {
		return "", false
	}

	dir, name := filepath.Split(filepath.Clean(strings.TrimSpace(gitDir)))
	if name == "" || filepath.Base(filepath.Clean(dir)) != "worktrees" {
		return "", false
	}

	return filepath.Dir(filepath.Dir(filepath.Clean(dir))), true
}

// jjWorkspaceParent reads a secondary workspace's ".jj/repo" file, which holds
// the path of the shared repo directory.
func jjWorkspaceParent(repoPath string) (string, bool) {
	contents, ok := pointerFile(filepath.Join(repoPath, ".jj", "repo"))
	if !ok {
		return "", false
	}

	repoDir := filepath.Clean(strings.TrimSpace(contents))
	if filepath.Base(repoDir) != "repo" || filepath.Base(filepath.Dir(repoDir)) != ".jj" {
		return "", false
	}

	return filepath.Dir(filepath.Dir(repoDir)), true
}

// pointerFile reads path when it is a regular file rather than a directory,
// which is how git and jj mark a linked checkout.
func pointerFile(path string) (string, bool) {
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return "", false
	}

	contents, err := os.ReadFile(path) // #nosec G304 -- path is a repo's own .git/.jj pointer
	if err != nil {
		return "", false
	}

	return string(contents), true
}
